interface WorkflowRun {
  id: number
  name?: string
  node_id?: string
  head_branch?: string
  head_sha?: string
  run_number?: number
  event?: string
  status?: string
  conclusion?: string | null
  workflow_id?: number
  check_suite_id?: number
  check_suite_node_id?: string
  url?: string
  html_url?: string
  created_at?: string
  updated_at?: string
}

