import {mainQuery} from '@github-ui/react-core/future/main-query'
import {deployFormAppBuilder} from '../config/app-builder'
import type {WebCommitInfo} from '@github-ui/code-view-types'

export type DeployFormResponse = {
  workflowFilePath: string
  webCommitInfo: WebCommitInfo
  branch: string
  framework: string | undefined
  packageManager: string | undefined
}

export const deployFormRoute = deployFormAppBuilder.createQueryRouteConfig('deployFormRoute', {
  path: '/:user_id/:repository/deploy',
  queries: [mainQuery<DeployFormResponse>()],
})
